namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public string Department { get; set; } = "";
    public bool IsFeatured { get; set; }
}

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Course> _courses = new()
    {
        new Course { Id = 1, CourseCode = "CS101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of computer science including algorithms, data structures, and problem solving.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in computer science education and specializes in algorithms.", Department = "Computer Science", IsFeatured = true },
        new Course { Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures such as lists, stacks, queues, trees, and graphs along with algorithm design and analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in computer science education and specializes in algorithms.", Department = "Computer Science", IsFeatured = false },
        new Course { Id = 3, CourseCode = "CS301", Title = "Database Systems", Description = "Introduction to database design, SQL, normalization, and modern database management systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Brian Kumar", InstructorBio = "Prof. Kumar is a database researcher with publications in distributed systems and data modeling.", Department = "Computer Science", IsFeatured = true },
        new Course { Id = 4, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Sarah Miller", InstructorBio = "Dr. Miller is an award-winning mathematics educator with a focus on making calculus accessible.", Department = "Mathematics", IsFeatured = true },
        new Course { Id = 5, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications in science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Sarah Miller", InstructorBio = "Dr. Miller is an award-winning mathematics educator with a focus on making calculus accessible.", Department = "Mathematics", IsFeatured = false },
        new Course { Id = 6, CourseCode = "MATH301", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, and statistical inference.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Park", InstructorBio = "Prof. Park specializes in applied statistics and has consulted for several Fortune 500 companies.", Department = "Mathematics", IsFeatured = false },
        new Course { Id = 7, CourseCode = "ENG101", Title = "English Composition", Description = "Develop effective writing skills through essay writing, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is a published author and has taught writing at the university level for over a decade.", Department = "English", IsFeatured = false },
        new Course { Id = 8, CourseCode = "ENG201", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major authors and literary movements.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is a published author and has taught writing at the university level for over a decade.", Department = "English", IsFeatured = true },
        new Course { Id = 9, CourseCode = "ENG301", Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing with peer review and revision strategies.", Credits = 3, Schedule = "Fri 1:00–3:45 PM", InstructorName = "Prof. James Wright", InstructorBio = "Prof. Wright is a novelist and poet whose works have appeared in numerous literary journals.", Department = "English", IsFeatured = false },
        new Course { Id = 10, CourseCode = "CS401", Title = "Software Engineering", Description = "Principles and practices of software engineering including requirements, design, testing, and project management.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Brian Kumar", InstructorBio = "Prof. Kumar is a database researcher with publications in distributed systems and data modeling.", Department = "Computer Science", IsFeatured = false },
    };

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<string> GetDepartments() =>
        _courses.Select(c => c.Department).Distinct().OrderBy(d => d).ToList();

    public Course? GetCourseById(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? department)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(department))
        {
            query = query.Where(c =>
                c.Department.Equals(department, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollment(EnrollmentRequest request) => true;
}

@page "/courses"
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title or course code..." />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept" selected="@(dept == Department)">@dept</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary">Search</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, Department);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="row">
        @foreach (var course in courses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                        <p class="card-text">
                            <span class="badge bg-secondary">@course.Department</span>
                            <span class="badge bg-info text-dark">@course.Credits Credits</span>
                        </p>
                    </div>
                    <div class="card-footer">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enroll</PageTitle>

<h1>Course Enrollment</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
        <strong>@(Catalog.GetCourseById(Model.CourseId)?.Title ?? "the selected course")</strong>
        has been received.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <form method="post" @formname="enrollment">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            <option value="@course.Id" selected="@(course.Id == Model.CourseId)">
                                @course.CourseCode — @course.Title
                            </option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment</button>
                <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private bool _submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET")
            && Model.CourseId > 0
            && !string.IsNullOrWhiteSpace(Model.StudentName))
        {
            Catalog.SubmitEnrollment(Model);
            _submitted = true;
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContextAccessor { get; set; }
}

