        new Course { Id = 4, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Sarah Miller", InstructorBio = "Dr. Miller is an award-winning mathematics educator with a focus on making calculus accessible.", Department = "Mathematics", IsFeatured = true },
